import{_ as n,c as a,a0 as r,o as t}from"./chunks/framework.CY2JQc0e.js";const j=JSON.parse('{"title":"Inschrijven","description":"","frontmatter":{"prev":false,"next":false},"headers":[],"relativePath":"nl/challenge/register/index.md","filePath":"nl/challenge/register/index.md"}'),s={name:"nl/challenge/register/index.md"};function i(l,e,d,o,m,c){return t(),a("div",null,e[0]||(e[0]=[r('<h1 id="inschrijven" tabindex="-1">Inschrijven <a class="header-anchor" href="#inschrijven" aria-label="Permalink to &quot;Inschrijven&quot;">​</a></h1><p>Deelname aan de wedstrijd is <strong>gratis</strong>. Als <strong>leerling</strong> hoef je alleen maar je wens om deel te nemen aan de wedstrijd kenbaar te maken aan een leerkracht op je school die de wedstrijd organiseert, zodat die je kan inschrijven.</p><p>Het is m.a.w. de <strong>leerkracht</strong> die de inschrijvingen van de leerlingen beheert.</p><p>Er zijn verschillende manieren waarop je je als leerkracht kan registreren bij de wedstrijd-server:</p><details class="details custom-block"><summary>Je hebt al eerder (online) aan de wedstrijd deelgenomen</summary><p>In dit geval kan je opnieuw deelnemen zonder dat je je opnieuw hoeft te inschrijven.</p><p><em>Je hoeft alleen je huidige inloggegevens te gebruiken om verbinding te maken met het wedstrijdplatform. Je kan dan nieuwe klassen aanmaken en een lijst met deelnemende leerlingen uploaden.</em></p></details><details class="details custom-block"><summary>Je kent een collega (uit dezelfde school) die al op het wedstrijdplatform is geregistreerd.</summary><p>In dit geval kan jouw collega je inschrijven.</p><p><em>Hij heeft enkel jouw school-e-mailadres nodig om je te registreren bij het wedstrijdplatform.</em></p></details><details class="details custom-block"><summary>Nieuw bij Bebras?</summary><p><em>Stuur dan een e-mail naar Kris Coolsaet (<a href="mailto:kris.coolsaet@ugent.be" target="_blank" rel="noreferrer">kris.coolsaet@ugent.be</a>), vanuit je school-e-mailadres. Vermeld ook de naam en het adres van je school.</em></p></details>',7)]))}const g=n(s,[["render",i]]);export{j as __pageData,g as default};
